-- ######## Window rules ########

-- Disable blur for xwayland context menus
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    match = {
        class = "^()$",
        title = "^()$",
    },
    no_blur = true,
})

-- Disable blur for every window
hl.window_rule({
    match = {
        class = ".*",
    },
    no_blur = true,
})

-- Floating
hl.window_rule({
    match = {
        title = "^(Open File)(.*)$",
    },
    center = true,
    float = true,
})

hl.window_rule({
    match = {
        title = "^(Select a File)(.*)$",
    },
    center = true,
    float = true,
})

hl.window_rule({
    match = {
        title = "^(Choose wallpaper)(.*)$",
    },
    center = true,
    float = true,
    size = "(monitor_w*.60) (monitor_h*.65)",
})

hl.window_rule({
